import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_CPP_SRC = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups);
"""

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/util/Optional.h>
#include <cstdint>

#include <algorithm>
constexpr int BM = 64;
constexpr int BN = 32;
constexpr int BK = 32;
constexpr int TM = 4;
constexpr int TN = 2;
__global__ void conv_transpose2d_implicit_gemm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    int N,
    int Cin,
    int Cout,
    int H,
    int W,
    int Ho,
    int Wo,
    int KH,
    int KW,
    int sh,
    int sw,
    int ph,
    int pw,
    int dh,
    int dw,
    int groups,
    bool has_bias) {
  const int Opg = Cout / groups;
  const int Ipg = Cin / groups;
  const int K = Ipg * KH * KW;
  const int M = Ho * Wo;
  __shared__ float As[BM][BK];
  __shared__ float Bs[BK][BN];
  const int tid = threadIdx.y * blockDim.x + threadIdx.x;
  const int tx = threadIdx.x;
  const int ty = threadIdx.y;
  for (int z = blockIdx.z; z < N * groups; z += gridDim.z) {
    const int n = z / groups;
    const int g = z - n * groups;
    const int ci_base = g * Ipg;
    const int co_local0 = blockIdx.x * BN;
    const int m0 = blockIdx.y * BM;
    float acc[TM][TN];
    #pragma unroll
    for (int tm = 0; tm < TM; ++tm) {
      #pragma unroll
      for (int tn = 0; tn < TN; ++tn) acc[tm][tn] = 0.0f;
    }
    for (int k0 = 0; k0 < K; k0 += BK) {
      #pragma unroll
      for (int r = 0; r < (BM * BK) / (BM / TM * BN / TN); ++r) {
        const int idx = tid + r * (BM / TM * BN / TN);
        const int bm = idx / BK;
        const int bk = idx - bm * BK;
        const int m = m0 + bm;
        const int k = k0 + bk;
        float av = 0.0f;
        if (m < M && k < K) {
          const int tap = KH * KW;
          const int i = k / tap;
          const int rem = k - i * tap;
          const int kh = rem / KW;
          const int kw = rem - kh * KW;
          const int oh = m / Wo;
          const int ow = m - oh * Wo;
          const int64_t th = static_cast<int64_t>(oh) + ph - static_cast<int64_t>(kh) * dh;
          const int64_t tw = static_cast<int64_t>(ow) + pw - static_cast<int64_t>(kw) * dw;
          if (th >= 0 && tw >= 0 && (th % sh) == 0 && (tw % sw) == 0) {
            const int h = static_cast<int>(th / sh);
            const int iw = static_cast<int>(tw / sw);
            if (h < H && iw < W) {
              av = x[(static_cast<int64_t>(n) * Cin + ci_base + i) * H * W + static_cast<int64_t>(h) * W + iw];
            }
          }
        }
        As[bm][bk] = av;
      }
      #pragma unroll
      for (int r = 0; r < (BK * BN) / (BM / TM * BN / TN); ++r) {
        const int idx = tid + r * (BM / TM * BN / TN);
        const int bk = idx / BN;
        const int bn = idx - bk * BN;
        const int k = k0 + bk;
        const int co_local = co_local0 + bn;
        float bv = 0.0f;
        if (k < K && co_local < Opg) {
          const int tap = KH * KW;
          const int i = k / tap;
          const int rem = k - i * tap;
          bv = w[(static_cast<int64_t>(ci_base + i) * Opg + co_local) * tap + rem];
        }
        Bs[bk][bn] = bv;
      }
      __syncthreads();
      const int kend = min(BK, K - k0);
      #pragma unroll
      for (int kk = 0; kk < BK; ++kk) {
        if (kk >= kend) break;
        float breg[TN];
        #pragma unroll
        for (int tn = 0; tn < TN; ++tn) breg[tn] = Bs[kk][tx * TN + tn];
        #pragma unroll
        for (int tm = 0; tm < TM; ++tm) {
          const float areg = As[ty * TM + tm][kk];
          #pragma unroll
          for (int tn = 0; tn < TN; ++tn) acc[tm][tn] += areg * breg[tn];
        }
      }
      __syncthreads();
    }
    #pragma unroll
    for (int tm = 0; tm < TM; ++tm) {
      const int m = m0 + ty * TM + tm;
      if (m >= M) continue;
      const int oh = m / Wo;
      const int ow = m - oh * Wo;
      #pragma unroll
      for (int tn = 0; tn < TN; ++tn) {
        const int co_local = co_local0 + tx * TN + tn;
        if (co_local >= Opg) continue;
        const int co = g * Opg + co_local;
        float outv = acc[tm][tn];
        if (has_bias) outv += b[co];
        y[(static_cast<int64_t>(n) * Cout + co) * M + m] = outv;
      }
    }
  }
}
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w,
    int64_t groups) {
  TORCH_CHECK(input.is_cuda(), "input must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
  TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
  TORCH_CHECK(groups > 0, "groups must be positive");
  auto x = input.contiguous();
  auto w = weight.contiguous();
  const int64_t N = x.size(0);
  const int64_t Cin = x.size(1);
  const int64_t H = x.size(2);
  const int64_t W = x.size(3);
  const int64_t Cout = w.size(1) * groups;
  const int64_t KH = w.size(2);
  const int64_t KW = w.size(3);
  TORCH_CHECK(w.size(0) == Cin, "weight/input channel mismatch");
  TORCH_CHECK(Cin % groups == 0, "in_channels must be divisible by groups");
  TORCH_CHECK(Cout % groups == 0, "out_channels must be divisible by groups");
  const int64_t Ho = (H - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + 1;
  const int64_t Wo = (W - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + 1;
  TORCH_CHECK(Ho > 0 && Wo > 0, "invalid output size");
  TORCH_CHECK(Ho * Wo <= std::numeric_limits<int>::max(), "output spatial size too large");
  auto y = torch::empty({N, Cout, Ho, Wo}, x.options());
  const bool has_bias =
      bias.has_value() && bias->defined() && bias->numel() == Cout;
  const float* b_ptr = nullptr;
  torch::Tensor bc;
  if (has_bias) {
    TORCH_CHECK(bias->is_cuda(), "bias must be CUDA");
    TORCH_CHECK(bias->scalar_type() == torch::kFloat32, "bias must be float32");
    bc = bias->contiguous();
    b_ptr = bc.data_ptr<float>();
  }
  const int64_t Opg = Cout / groups;
  const dim3 block(BN / TN, BM / TM, 1);
  const unsigned int gx = static_cast<unsigned int>((Opg + BN - 1) / BN);
  const unsigned int gy = static_cast<unsigned int>((Ho * Wo + BM - 1) / BM);
  const unsigned int gz = static_cast<unsigned int>(std::min<int64_t>(N * groups, 65535));
  const dim3 grid(gx, gy, gz);
  cudaStream_t stream = at::cuda::getCurrentCUDAStream();
  conv_transpose2d_implicit_gemm_kernel<<<grid, block, 0, stream>>>(
      x.data_ptr<float>(),
      w.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      static_cast<int>(N),
      static_cast<int>(Cin),
      static_cast<int>(Cout),
      static_cast<int>(H),
      static_cast<int>(W),
      static_cast<int>(Ho),
      static_cast<int>(Wo),
      static_cast<int>(KH),
      static_cast<int>(KW),
      static_cast<int>(stride_h),
      static_cast<int>(stride_w),
      static_cast<int>(pad_h),
      static_cast<int>(pad_w),
      static_cast<int>(dil_h),
      static_cast<int>(dil_w),
      static_cast<int>(groups),
      has_bias);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
"""

_mod = load_inline(
    name="custom_conv_transpose2d_gather",
    cpp_sources=_CPP_SRC,
    cuda_sources=_CUDA_SRC,
    functions=["conv_transpose2d_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False,
    ):
        super(ModelNew, self).__init__()
        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )
        self.stride = tuple(stride)
        self.padding = tuple(padding)
        self.dilation = tuple(dilation)
        self.groups = groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv_transpose2d.bias
        return _mod.conv_transpose2d_cuda(
            x,
            self.conv_transpose2d.weight,
            bias,
            self.stride[0],
            self.stride[1],
            self.padding[0],
            self.padding[1],
            self.dilation[0],
            self.dilation[1],
            self.groups,
        )

