__global__ void conv_transpose2d_gather_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    int N,
    int Cin,
    int Cout,
    int H,
    int W,
    int Ho,
    int Wo,
    int KH,
    int KW,
    int sh,
    int sw,
    int ph,
    int pw,
    int dh,
    int dw,
    int groups,
    bool has_bias) {
  const int Opg = Cout / groups;
  const int Ipg = Cin / groups;

  for (int z = blockIdx.z; z < N * Cout; z += gridDim.z) {
    const int n = z / Cout;
    const int co = z - n * Cout;

    const int ow = blockIdx.x * blockDim.x + threadIdx.x;
    const int oh = blockIdx.y * blockDim.y + threadIdx.y;
    if (ow >= Wo || oh >= Ho) continue;

    const int g = co / Opg;
    const int cow = co - g * Opg;
    const int ci_base = g * Ipg;

    float acc = 0.0f;

    for (int kh = 0; kh < KH; ++kh) {
      const int64_t th = static_cast<int64_t>(oh) + ph - static_cast<int64_t>(kh) * dh;
      if (th < 0) continue;
      if ((th % sh) != 0) continue;
      const int h = static_cast<int>(th / sh);
      if (h >= H) continue;

      for (int kw = 0; kw < KW; ++kw) {
        const int64_t tw = static_cast<int64_t>(ow) + pw - static_cast<int64_t>(kw) * dw;
        if (tw < 0) continue;
        if ((tw % sw) != 0) continue;
        const int iw = static_cast<int>(tw / sw);
        if (iw >= W) continue;

        const int64_t x_base =
            (static_cast<int64_t>(n) * Cin + ci_base) * H * W +
            static_cast<int64_t>(h) * W + iw;
        const int64_t w_base =
            (static_cast<int64_t>(ci_base) * Opg + cow) * KH * KW +
            static_cast<int64_t>(kh) * KW + kw;

        for (int i = 0; i < Ipg; ++i) {
          const float xv = x[x_base + static_cast<int64_t>(i) * H * W];
          const float wv = w[w_base + static_cast<int64_t>(i) * Opg * KH * KW];
          acc += xv * wv;
        }
      }
    }

    if (has_bias) acc += b[co];
    y[(static_cast<int64_t>(z) * Ho + oh) * Wo + ow] = acc;
  }
}

